def transform(g):
    g=np.array(g);H,W=g.shape
    syms=[lambda r,c:(r,c),lambda r,c:(r,W-1-c),lambda r,c:(H-1-r,c),lambda r,c:(H-1-r,W-1-c),
          lambda r,c:(c,r),lambda r,c:(c,W-1-r),lambda r,c:(H-1-c,r),lambda r,c:(H-1-c,W-1-r)]
    out=g.copy()
    for r in range(H):
        for c in range(W):
            if g[r,c]==2:
                vals=[g[s(r,c)] for s in syms if g[s(r,c)]!=2]
                if vals: out[r,c]=max(set(vals),key=vals.count)
    return out.tolist()
